<?php
namespace Tests\Feature\Admin;
use App\Enums\LeadStatus;use App\Livewire\Admin\CallCentre\Show as CallShow;use App\Livewire\Admin\WhatsApp\Show as WhatsAppShow;use App\Models\CallCenterCall;use App\Models\Lead;use App\Models\User;use App\Models\WhatsAppContact;use App\Models\WhatsAppConversation;use App\Models\WhatsAppMessage;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Facades\Bus;use Livewire\Livewire;use Tests\TestCase;
class CallCentreWhatsAppTest extends TestCase{use RefreshDatabase;
 public function test_assigned_call_centre_user_records_attempt_and_completes_call():void{$agent=User::factory()->create(['role'=>'call_center']);$lead=Lead::factory()->create();$call=CallCenterCall::create(['lead_id'=>$lead->id,'assigned_call_center_user'=>$agent->id,'call_type'=>'pre_departure','status'=>'assigned','call_attempts'=>0]);$this->actingAs($agent);Livewire::test(CallShow::class,['call'=>$call])->call('recordAttempt','not_answered')->assertHasNoErrors();$this->assertSame(1,$call->fresh()->call_attempts);Livewire::test(CallShow::class,['call'=>$call->fresh()])->set('status','completed')->set('call_notes','Customer confirmed documents')->call('save')->assertHasNoErrors();$this->assertSame('completed',$call->fresh()->status);}
 public function test_other_call_centre_user_cannot_open_assigned_call():void{$owner=User::factory()->create(['role'=>'call_center']);$other=User::factory()->create(['role'=>'call_center']);$call=CallCenterCall::create(['lead_id'=>Lead::factory()->create()->id,'assigned_call_center_user'=>$owner->id,'call_type'=>'post_arrival','status'=>'assigned']);$this->actingAs($other)->get(route('admin.calls.show',$call))->assertForbidden();}
 public function test_sales_whatsapp_conversion_assigns_new_lead_and_reply_is_queued():void{Bus::fake();$sales=User::factory()->create(['role'=>'sales']);$contact=WhatsAppContact::create(['wa_id'=>'94770000000','phone'=>'94770000000','profile_name'=>'WhatsApp Guest']);$chat=WhatsAppConversation::create(['whatsapp_contact_id'=>$contact->id,'assigned_to'=>$sales->id,'assigned_at'=>now(),'last_message_at'=>now(),'last_message_preview'=>'Need a holiday','unread_count'=>1]);WhatsAppMessage::create(['whatsapp_conversation_id'=>$chat->id,'wamid'=>'wamid-test','direction'=>'inbound','type'=>'text','body'=>'Need a holiday','status'=>'received','sent_at'=>now()]);$this->actingAs($sales);Livewire::test(WhatsAppShow::class,['conversation'=>$chat])->set('reply','We can help')->call('send')->assertHasNoErrors();$this->assertDatabaseHas('whatsapp_messages',['direction'=>'outbound','body'=>'We can help']);Livewire::test(WhatsAppShow::class,['conversation'=>$chat->fresh()])->call('convert')->assertHasNoErrors();$lead=$chat->fresh()->lead;$this->assertSame($sales->id,$lead->assigned_to);$this->assertSame(LeadStatus::ASSIGNED_TO_SALES->value,$lead->status);}
}
